"""Every rounding rule of meterbill lives here.

All decimal rounding is done with exact integer arithmetic, so nothing in
this module reads or depends on the decimal context.
"""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _fraction(value: Decimal) -> Fraction:
    return Fraction(value)


def _make(negative: bool, units: int, exponent: int) -> Decimal:
    digits = tuple(int(c) for c in str(units))
    return Decimal((1 if negative else 0, digits, exponent))


def _is_negative(value: Decimal) -> bool:
    return value.is_signed()


def _add(a: Decimal, b: Decimal) -> Decimal:
    """Exact sum, with the exponent and the sign of zero of a decimal addition."""
    ea, eb = a.as_tuple().exponent, b.as_tuple().exponent
    exp = min(ea, eb)
    total = _fraction(a) + _fraction(b)
    units = total / Fraction(10) ** exp
    n = int(units)
    if n == 0:
        return _make(a.is_signed() and b.is_signed(), 0, exp)
    return _make(n < 0, abs(n), exp)


def _neg(a: Decimal) -> Decimal:
    return _make(not a.is_signed(), abs(int("".join(map(str, a.as_tuple().digits)))), a.as_tuple().exponent)


def _sum(values, start: Decimal) -> Decimal:
    total = start
    for v in values:
        total = _add(total, v)
    return total


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` rules ties and direction."""
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")
    ratio = _fraction(value) / _fraction(step)
    magnitude = abs(ratio)
    n = magnitude.numerator // magnitude.denominator
    rem = magnitude - n
    if method != DOWN:
        half = Fraction(1, 2)
        if rem > half or (rem == half and (method == HALF_UP or n % 2 == 1)):
            n += 1
    st = step.as_tuple()
    step_units = int("".join(map(str, st.digits)))
    return _make(value.is_signed(), n * step_units, st.exponent)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """Cut each amount down to `step`; the loss against the rounded total goes
    on the last amount that is not zero."""
    parts = [round_amount(a, step, DOWN) for a in amounts]
    exact = sum((_fraction(a) for a in amounts), Fraction(0))
    whole = round_amount(_exact_decimal(exact), step, HALF_UP)
    zero = round_amount(Decimal(0), step, DOWN)
    rest = _add(whole, _neg(_sum(parts, zero)))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return parts


def _exact_decimal(f: Fraction) -> Decimal:
    """A Fraction whose denominator is a product of 2s and 5s, as an exact Decimal."""
    d = f.denominator
    k = 0
    while (10**k) % d:
        k += 1
    n = f.numerator * (10**k // d)
    return _make(n < 0, abs(n), -k)


def legacy_cents(value: float, places: int = 2) -> float:
    """A float settled the way the old customer system settled it (binary floating point)."""
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point."""
    if isinstance(value, Decimal):
        step = _make(False, 1, -places)
        return format(round_amount(value, step, method), "f")
    if method != HALF_EVEN:
        raise ValueError("a float can only be written half-even")
    return format(value, f".{places}f")
E

